        x = 1;
        check_output(1'b0);

        // In State B: apply x=0 -> expect z=1, stay in B
        x = 0;
        check_output(1'b1);

        // Test 3: Asynchronous Reset recovery during operation
        areset = 1;
        #3;
        if (z !== 1'b0) begin
            $display("Time %0t: Asynchronous reset activation error! z=%b", $time, z);
            errors = errors + 1;
        end

        areset = 0;
        x = 1;
